-- Voice Memo App
-- Import via phpMyAdmin or: mysql -u root -P 3306 < schema.sql
-- Creates database, schema, and demo seed data.
-- Memo timestamps use NOW()-relative expressions (DATE_SUB(NOW(), INTERVAL n HOUR))
-- so lists/search/recency all look live no matter when this file is imported.
-- Every seeded `summary` was generated by running the app's own
-- core/Summarizer.php against the seeded `transcript` (a throwaway generator
-- script, not shipped) -- nothing here is hand-faked, same practice as
-- project #13's Sentiment-based seed data.

CREATE DATABASE IF NOT EXISTS voice_memo_app
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE voice_memo_app;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS memo_tags;
DROP TABLE IF EXISTS tags;
DROP TABLE IF EXISTS memos;
DROP TABLE IF EXISTS folders;
DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================
-- Schema
-- ============================================================

CREATE TABLE users (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    name          VARCHAR(100) NOT NULL,
    email         VARCHAR(150) NOT NULL UNIQUE,
    password      VARCHAR(255) NOT NULL,
    role          ENUM('super_admin','user') NOT NULL,
    status        ENUM('active','inactive') NOT NULL DEFAULT 'active',
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE folders (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    user_id       INT NOT NULL,
    name          VARCHAR(60) NOT NULL,
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uniq_user_folder (user_id, name),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE memos (
    id                INT AUTO_INCREMENT PRIMARY KEY,
    user_id           INT NOT NULL,
    folder_id         INT NULL,
    title             VARCHAR(150) NOT NULL,
    audio_path        VARCHAR(255) NOT NULL,
    audio_mime        VARCHAR(100) NOT NULL,
    duration_seconds  INT NOT NULL DEFAULT 0,
    source            ENUM('recorded','uploaded') NOT NULL DEFAULT 'recorded',
    transcript        MEDIUMTEXT NULL,
    summary           MEDIUMTEXT NULL,
    is_starred        TINYINT(1) NOT NULL DEFAULT 0,
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (folder_id) REFERENCES folders(id) ON DELETE SET NULL,
    KEY idx_memos_user_created (user_id, created_at)
) ENGINE=InnoDB;

CREATE TABLE tags (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    name          VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE memo_tags (
    memo_id       INT NOT NULL,
    tag_id        INT NOT NULL,
    PRIMARY KEY (memo_id, tag_id),
    FOREIGN KEY (memo_id) REFERENCES memos(id) ON DELETE CASCADE,
    FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE
) ENGINE=InnoDB;

