-- ---- memos ----
INSERT INTO memos (id, user_id, folder_id, title, audio_path, audio_mime, duration_seconds, source, transcript, summary, is_starred, created_at, updated_at) VALUES
(1, 2, 1, 'Sprint standup notes', 'memos/demo-silence.wav', 'audio/wav', 74, 'recorded', 'Quick standup notes for the sprint. The backend team finished the payment gateway integration ahead of schedule this week. QA found two blocking bugs in the checkout flow that need fixes before Friday''s release. I need to follow up with the design team about the new onboarding screens, since Priya mentioned the mockups are almost ready. We should also revisit the caching strategy for the product listing page because a customer complained about slow load times yesterday. Overall the sprint is on track, so I am fairly confident we can ship by the deadline.', 'Quick standup notes for the sprint. QA found two blocking bugs in the checkout flow that need fixes before Friday''s release.', 1, DATE_SUB(NOW(), INTERVAL 6 HOUR), DATE_SUB(NOW(), INTERVAL 6 HOUR)),
(2, 2, 2, 'Dark mode and export ideas', 'memos/demo-silence.wav', 'audio/wav', 38, 'recorded', 'Idea for the app: what if we added a dark mode toggle that remembers the user''s system preference automatically. Another idea is to let users export their notes as a PDF directly from the settings page. I also want to explore adding keyboard shortcuts for power users navigating the dashboard quickly. Worth prototyping this weekend if I have time.', 'Another idea is to let users export their notes as a PDF directly from the settings page. I also want to explore adding keyboard shortcuts for power users navigating the dashboard quickly.', 0, DATE_SUB(NOW(), INTERVAL 30 HOUR), DATE_SUB(NOW(), INTERVAL 30 HOUR)),
(3, 2, NULL, 'Voice note from car', 'memos/demo-silence.wav', 'audio/wav', 12, 'uploaded', NULL, NULL, 0, DATE_SUB(NOW(), INTERVAL 50 HOUR), DATE_SUB(NOW(), INTERVAL 50 HOUR)),
(4, 2, 1, 'Deployment runbook fix', 'memos/demo-silence.wav', 'audio/wav', 29, 'recorded', 'Reminder to update the deployment runbook after today''s release since two steps were missing and caused confusion. Also need to schedule a knowledge-sharing session about the new logging pipeline for the rest of the team.', 'Reminder to update the deployment runbook after today''s release since two steps were missing and caused confusion.', 0, DATE_SUB(NOW(), INTERVAL 100 HOUR), DATE_SUB(NOW(), INTERVAL 100 HOUR)),
(5, 2, 2, 'Lock screen quick-capture idea', 'memos/demo-silence.wav', 'audio/wav', 15, 'recorded', 'One more idea, a quick capture shortcut on the lock screen so I do not have to unlock the phone just to record a fleeting thought.', 'One more idea, a quick capture shortcut on the lock screen so I do not have to unlock the phone just to record a fleeting thought.', 0, DATE_SUB(NOW(), INTERVAL 130 HOUR), DATE_SUB(NOW(), INTERVAL 130 HOUR)),
(6, 3, 3, 'Database systems lecture', 'memos/demo-silence.wav', 'audio/wav', 95, 'recorded', 'Today''s database systems lecture covered normalization up to third normal form and why redundancy causes update anomalies. The professor explained functional dependencies with a detailed example involving a student course enrollment table. She also mentioned that the midterm will include at least one question on decomposition and lossless joins. I should review the practice problems from chapter six before next week. The lecture ended with a brief preview of indexing and B-tree structures for the next class.', 'Today''s database systems lecture covered normalization up to third normal form and why redundancy causes update anomalies. The professor explained functional dependencies with a detailed example involving a student course enrollment table.', 1, DATE_SUB(NOW(), INTERVAL 20 HOUR), DATE_SUB(NOW(), INTERVAL 20 HOUR)),
(7, 3, 4, 'Weekend reminders', 'memos/demo-silence.wav', 'audio/wav', 22, 'recorded', 'Reminder to myself, call mom this weekend and ask about the family trip dates for December. Also need to pick up the dry cleaning before Thursday. I keep forgetting to water the plants so I should set a recurring reminder for that too.', 'Reminder to myself, call mom this weekend and ask about the family trip dates for December.', 1, DATE_SUB(NOW(), INTERVAL 45 HOUR), DATE_SUB(NOW(), INTERVAL 45 HOUR)),
(8, 3, NULL, 'Grocery run', 'memos/demo-silence.wav', 'audio/wav', 9, 'uploaded', 'Buy milk and eggs on the way home.', 'Buy milk and eggs on the way home.', 0, DATE_SUB(NOW(), INTERVAL 60 HOUR), DATE_SUB(NOW(), INTERVAL 60 HOUR)),
(9, 3, 3, 'Distributed systems guest lecture', 'memos/demo-silence.wav', 'audio/wav', 110, 'recorded', 'Guest lecture summary on distributed systems consistency models. The speaker compared strong consistency and eventual consistency using a shopping cart example that made the tradeoffs very clear. She also touched on CAP theorem and why most real systems pick availability over strict consistency during a network partition. I want to re-watch the recording later since it moved quite fast in the last ten minutes.', 'Guest lecture summary on distributed systems consistency models. The speaker compared strong consistency and eventual consistency using a shopping cart example that made the tradeoffs very clear.', 1, DATE_SUB(NOW(), INTERVAL 150 HOUR), DATE_SUB(NOW(), INTERVAL 150 HOUR)),
(10, 3, 4, 'Doctor appointment reminder', 'memos/demo-silence.wav', 'audio/wav', 14, 'uploaded', 'Doctor''s appointment is confirmed for next Tuesday at eleven in the morning, remember to bring the previous prescription and the insurance card.', 'Doctor''s appointment is confirmed for next Tuesday at eleven in the morning, remember to bring the previous prescription and the insurance card.', 0, DATE_SUB(NOW(), INTERVAL 8 HOUR), DATE_SUB(NOW(), INTERVAL 8 HOUR)),
(11, 4, 5, 'Client call notes', 'memos/demo-silence.wav', 'audio/wav', 88, 'recorded', 'Notes from the client call this afternoon. The client wants the analytics dashboard delivered two weeks earlier than originally planned, which means we need to reprioritize the current sprint. They also requested an export to Excel feature that was not in the original scope. I promised to send a revised timeline by tomorrow morning. Overall the client seemed happy with the current progress and praised the new reporting module.', 'Notes from the client call this afternoon. Overall the client seemed happy with the current progress and praised the new reporting module.', 1, DATE_SUB(NOW(), INTERVAL 15 HOUR), DATE_SUB(NOW(), INTERVAL 15 HOUR)),
(12, 4, 6, 'Weekly reflection', 'memos/demo-silence.wav', 'audio/wav', 70, 'recorded', 'Reflecting on the week, I think I handled the production incident on Tuesday reasonably well even though it was stressful. I learned that our alerting setup has a blind spot for the payment service that we should fix soon. I also had a good conversation with my manager about taking on more ownership next quarter. Overall it was a productive week despite the rough start.', 'Reflecting on the week, I think I handled the production incident on Tuesday reasonably well even though it was stressful. Overall it was a productive week despite the rough start.', 0, DATE_SUB(NOW(), INTERVAL 40 HOUR), DATE_SUB(NOW(), INTERVAL 40 HOUR)),
(13, 4, NULL, 'Voice memo 3', 'memos/demo-silence.wav', 'audio/wav', 18, 'uploaded', NULL, NULL, 0, DATE_SUB(NOW(), INTERVAL 65 HOUR), DATE_SUB(NOW(), INTERVAL 65 HOUR)),
(14, 4, 5, 'Budget review meeting', 'memos/demo-silence.wav', 'audio/wav', 60, 'recorded', 'Budget review meeting notes. Finance approved the additional headcount request for the platform team starting next quarter. They asked for a more detailed breakdown of the cloud infrastructure costs before the next review. I need to loop in the DevOps lead to prepare that report.', 'Budget review meeting notes. Finance approved the additional headcount request for the platform team starting next quarter.', 0, DATE_SUB(NOW(), INTERVAL 120 HOUR), DATE_SUB(NOW(), INTERVAL 120 HOUR)),
(15, 5, 7, 'Sprint retro notes', 'memos/demo-silence.wav', 'audio/wav', 80, 'recorded', 'Project retro notes. The team agreed the biggest blocker this sprint was the flaky staging environment that kept failing deployments randomly. We decided to dedicate half a day next week purely to stabilizing the CI pipeline. Everyone liked the new daily async updates format better than the old standup meeting. I will draft a short proposal document and share it in the team channel tomorrow.', 'Project retro notes. Everyone liked the new daily async updates format better than the old standup meeting.', 1, DATE_SUB(NOW(), INTERVAL 25 HOUR), DATE_SUB(NOW(), INTERVAL 25 HOUR)),
(16, 5, NULL, 'Book recommendation', 'memos/demo-silence.wav', 'audio/wav', 11, 'recorded', 'Book recommendation for later, someone in the meeting mentioned a book about deep work and focus techniques for engineers.', 'Book recommendation for later, someone in the meeting mentioned a book about deep work and focus techniques for engineers.', 1, DATE_SUB(NOW(), INTERVAL 55 HOUR), DATE_SUB(NOW(), INTERVAL 55 HOUR)),
(17, 5, 7, 'Voice memo 4', 'memos/demo-silence.wav', 'audio/wav', 20, 'uploaded', NULL, NULL, 0, DATE_SUB(NOW(), INTERVAL 90 HOUR), DATE_SUB(NOW(), INTERVAL 90 HOUR)),
(18, 6, 8, 'Weekend trip planning', 'memos/demo-silence.wav', 'audio/wav', 65, 'recorded', 'Weekend trip planning notes. We are considering either the coastal town or the hill station for the long weekend in November. The coastal town has better weather this time of year but the hill station is closer and cheaper to reach. I should check hotel availability for both options before Friday. Also need to renew my travel insurance which expired last month.', 'Weekend trip planning notes. We are considering either the coastal town or the hill station for the long weekend in November.', 0, DATE_SUB(NOW(), INTERVAL 35 HOUR), DATE_SUB(NOW(), INTERVAL 35 HOUR)),
(19, 6, NULL, 'Interview debrief', 'memos/demo-silence.wav', 'audio/wav', 55, 'uploaded', 'Interview debrief. The candidate had strong system design skills but seemed weaker on the coding round, particularly with edge cases around concurrency. Communication was clear and they asked thoughtful questions about the team''s on-call rotation. I would lean towards a hire with a note to pair them with a senior engineer initially.', 'Interview debrief. The candidate had strong system design skills but seemed weaker on the coding round, particularly with edge cases around concurrency.', 0, DATE_SUB(NOW(), INTERVAL 48 HOUR), DATE_SUB(NOW(), INTERVAL 48 HOUR)),
(20, 6, 8, 'Errands reminder', 'memos/demo-silence.wav', 'audio/wav', 13, 'recorded', 'Quick voice note, remember to renew the car insurance before the fifteenth and also drop off the package at the courier office.', 'Quick voice note, remember to renew the car insurance before the fifteenth and also drop off the package at the courier office.', 0, DATE_SUB(NOW(), INTERVAL 5 HOUR), DATE_SUB(NOW(), INTERVAL 5 HOUR));

